const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: "summary",
  index: 8,
  title: "Key Takeaways: No Single Model Wins Everything — Specialization Is the New Frontier"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9.0, h: 0.8,
    fontSize: 24, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    valign: "middle", fit: "shrink", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.1, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  const takeaways = [
    "GPT-5.4 leads agentic coding and frontier reasoning — but not multimodal or safety",
    "Gemini dominates audio and vision-language benchmarks, sweeping all top positions on AudioMultiChallenge",
    "Claude leads safety and professional reasoning — 96%+ MASK honesty, #1 on Legal and Finance",
    "Key benchmarks remain far from saturation: HLE (44%), EnigmaEval (24%), SciPredict (25%)",
    "Muse Spark is a strong new competitor — top 3 on 6+ benchmarks, including #1 on MultiChallenge at 75.5%"
  ];

  const startY = 1.4;
  const itemH = 0.7;

  takeaways.forEach((text, i) => {
    const yPos = startY + i * itemH;

    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: yPos + 0.05, w: 0.35, h: 0.35,
      fill: { color: theme.accent }
    });

    slide.addText(String(i + 1), {
      x: 0.5, y: yPos + 0.05, w: 0.35, h: 0.35,
      fontSize: 13, fontFace: "Calibri",
      color: theme.primary, bold: true,
      align: "center", valign: "middle", margin: 0
    });

    slide.addText(text, {
      x: 1.05, y: yPos, w: 8.2, h: 0.45,
      fontSize: 13, fontFace: "Calibri",
      color: "FFFFFF", bold: false,
      align: "left", valign: "middle", margin: 0
    });
  });

  slide.addText("Source: Scale SEAL Leaderboards | scale.com/leaderboard", {
    x: 0.5, y: 5.2, w: 5.0, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: "AAAAAA", italic: true, margin: 0
  });

  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: theme.primary, bold: true,
    align: "center", valign: "middle", margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "e76f51"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

